CROSS JOIN LATERAL aclexplode(d.defaclacl) a
WHERE rl.rolname IN ('postgres', 'supabase_admin') AND (n.nspname = 'public' OR d.defaclnamespace = 0) AND d.defaclobjtype IN ('r', 'S', 'f')
