--
-- Name: prevent_booking_on_blocked_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."prevent_booking_on_blocked_date"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF LOWER(COALESCE(NEW.status, 'pending')) IN ('pending', 'confirmed')
       AND EXISTS (
           SELECT 1
           FROM public.blocked_dates
           WHERE event_date = NEW.event_date
       )
    THEN
        RAISE EXCEPTION
            'This date is unavailable. Please select another event date.';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_booking_on_blocked_date"() OWNER TO "postgres";

--
-- Name: prevent_role_escalation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."prevent_role_escalation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    IF NOT public.is_owner() THEN
      RAISE EXCEPTION 'Only the owner can change user roles.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_role_escalation"() OWNER TO "postgres";

--
-- Name: purge_archived_bookings(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."purge_archived_bookings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  booking_record record;
  purged_count integer := 0;
  purged_at timestamptz;
BEGIN
  FOR booking_record IN
    SELECT
      id,
      booking_reference,
      event_date,
      archived_at
    FROM public.bookings
    WHERE status = 'archived'
      AND archived_at IS NOT NULL
      AND archived_at <= pg_catalog.now() - interval '6 months'
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      IF EXISTS (
        SELECT 1
        FROM public.payments
        WHERE booking_id = booking_record.id
      ) THEN
        CONTINUE;
      END IF;

      purged_at := pg_catalog.now();

      DELETE FROM public.bookings
      WHERE id = booking_record.id
        AND status = 'archived'
        AND archived_at IS NOT NULL
        AND archived_at <= pg_catalog.now() - interval '6 months'
        AND NOT EXISTS (
          SELECT 1
          FROM public.payments
          WHERE booking_id = booking_record.id
        );

      IF FOUND THEN
        INSERT INTO public.audit_logs (
          actor_user_id,
          action,
          target_user_id,
          metadata,
          created_at
        )
        VALUES (
          NULL,
          'booking.auto_purged',
          NULL,
          pg_catalog.jsonb_build_object(
            'booking_reference', booking_record.booking_reference,
            'event_date', booking_record.event_date,
            'archived_at', booking_record.archived_at,
            'purged_at', purged_at
          ),
          purged_at
        );

        purged_count := purged_count + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING
        'Archived booking purge failed for %: %',
        booking_record.id,
        SQLERRM;
    END;
  END LOOP;

  RETURN purged_count;
END;
$$;


ALTER FUNCTION "public"."purge_archived_bookings"() OWNER TO "postgres";

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: postgres
--

-- [stage4 R3] rls_auto_enable(): created only if the target does not already have it (a fresh Supabase project may ship it, owned by another role).
DO $stage4_conditional$
BEGIN
  IF to_regprocedure('public.rls_auto_enable()') IS NULL THEN
    EXECUTE $stage4_sql$
CREATE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;
$stage4_sql$;
    EXECUTE $stage4_sql$ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";$stage4_sql$;
    EXECUTE $stage4_sql$REVOKE ALL ON FUNCTION "public"."rls_auto_enable"() FROM PUBLIC;$stage4_sql$;
  ELSE
    RAISE NOTICE 'stage4: public.rls_auto_enable() already exists on the target; production definition NOT applied (compare it manually).';
  END IF;
END
$stage4_conditional$;


