-- ---------------------------------------------------------------------------------------------------------------------------------
RESET statement_timeout;
RESET lock_timeout;
RESET idle_in_transaction_session_timeout;
RESET transaction_timeout;
RESET client_encoding;
RESET standard_conforming_strings;
RESET search_path;
RESET check_function_bodies;
RESET xmloption;
RESET client_min_messages;
RESET row_security;
RESET default_table_access_method;

DO $stage4_postcondition$
DECLARE
  v_tables int; v_rls int; v_forced int; v_triggers int; v_policies int; v_indexes int; v_functions int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE c.relrowsecurity), count(*) FILTER (WHERE c.relforcerowsecurity) INTO v_tables, v_rls, v_forced
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind = 'r';
  SELECT count(*) INTO v_triggers FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND NOT t.tgisinternal;
  SELECT count(*) INTO v_policies FROM pg_policies WHERE schemaname = 'public';
  SELECT count(*) INTO v_indexes FROM pg_indexes WHERE schemaname = 'public';
  SELECT count(*) INTO v_functions FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public';
  IF v_tables <> 12 OR v_rls <> 12 OR v_forced <> 0 THEN RAISE EXCEPTION 'STAGE4 POSTCONDITION: tables/RLS mismatch (% tables, % with RLS, % forced)', v_tables, v_rls, v_forced; END IF;
  IF v_triggers <> 10 THEN RAISE EXCEPTION 'STAGE4 POSTCONDITION: expected 10 triggers, found %', v_triggers; END IF;
  IF v_policies <> 35 THEN RAISE EXCEPTION 'STAGE4 POSTCONDITION: expected 35 policies, found %', v_policies; END IF;
  IF v_indexes <> 42 THEN RAISE EXCEPTION 'STAGE4 POSTCONDITION: expected 42 indexes (incl. primary/unique), found %', v_indexes; END IF;
  IF v_functions <> 12 THEN RAISE EXCEPTION 'STAGE4 POSTCONDITION: expected 12 functions, found %', v_functions; END IF;
END
$stage4_postcondition$;

